DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `country` bigint(20) DEFAULT NULL,
  `mobile_no` bigint(20) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `user_type` varchar(255) DEFAULT NULL,
  `login_type` text DEFAULT NULL,
  `is_subscribe` int(11) DEFAULT NULL,
  `subscription_id` int(11) DEFAULT NULL,
  `subscription_start_date` varchar(255) DEFAULT NULL,
  `subscription_end_date` varchar(255) DEFAULT NULL,
  `business_limit` int(11) DEFAULT 1,
  `custom_post_used` int(11) NOT NULL DEFAULT 0 COMMENT 'Custom Posts used this month',
  `festival_post_used` int(11) NOT NULL DEFAULT 0,
  `category_post_used` int(11) NOT NULL DEFAULT 0,
  `photoroom_bg_used` int(11) NOT NULL DEFAULT 0,
  `daily_drip_used` int(11) NOT NULL DEFAULT 0 COMMENT 'Daily Drip posts used this month',
  `magic_cloner_used` int(11) NOT NULL DEFAULT 0 COMMENT 'AI Magic Cloner uses this month',
  `limits_reset_at` timestamp NULL DEFAULT NULL COMMENT 'When the monthly usage counters were last reset',
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `referral_code` varchar(255) DEFAULT NULL,
  `is_partner` tinyint(1) NOT NULL DEFAULT 0,
  `partner_commission_percent` decimal(5,2) DEFAULT NULL,
  `total_partner_earnings` decimal(10,2) NOT NULL DEFAULT 0.00,
  `current_balance` bigint(20) NOT NULL DEFAULT 0,
  `total_balance` bigint(20) NOT NULL DEFAULT 0,
  `status` int(11) NOT NULL DEFAULT 1,
  `api_token` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `last_notification_read_at` timestamp NULL DEFAULT NULL,
  `watermark` tinyint(1) NOT NULL DEFAULT 0,
  `user_languages` text DEFAULT NULL,
  `app_language` varchar(191) NOT NULL DEFAULT 'English',
  `preferred_languages` text DEFAULT NULL,
  `add_watermark` tinyint(1) NOT NULL DEFAULT 1,
  `dark_mode` tinyint(4) NOT NULL DEFAULT 0,
  `add_share_text` tinyint(4) NOT NULL DEFAULT 1,
  `is_watermark` tinyint(1) NOT NULL DEFAULT 0,
  `custom_post_ad_used` int(11) NOT NULL DEFAULT 0,
  `daily_drip_ad_used` int(11) NOT NULL DEFAULT 0,
  `magic_cloner_ad_used` int(11) NOT NULL DEFAULT 0,
  `festival_post_ad_used` int(11) NOT NULL DEFAULT 0,
  `category_ad_used` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `idx_users_apitoken` (`api_token`(768)),
  KEY `idx_users_referralcode` (`referral_code`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
